// lifebar/config — the bar's seven palette roles and font, as key=value
// lines (lifebar/src/config.rs reads them). Size is the theme font size in
// CSS pixels, as waybar's stylesheet used it, so the bar keeps its size when
// it replaces waybar.

use crate::theme::{bare, plain_name, Theme};

pub fn render(t: &Theme) -> String {
    let p = &t.palette;
    format!(
        "# lifebar — generated by lifeconf.\n\
         # Edit ~/.config/lifeconf/theme.toml (or run `lifeconf`), not this file.\n\
         font={family}\n\
         size={size}\n\
         height=26\n\
         bg={bg}\n\
         surface={surface}\n\
         border={border}\n\
         text={text}\n\
         accent={accent}\n\
         warn={warn}\n\
         urgent={urgent}\n",
        family = plain_name(&t.font.family),
        size = t.accessibility.scaled(t.font.size as f64),
        bg = bare(&p.bg),
        surface = bare(&p.surface),
        border = bare(&p.border),
        text = bare(&p.text),
        accent = bare(&p.accent),
        warn = bare(&p.warn),
        urgent = bare(&p.urgent),
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_role_and_the_font() {
        let t = Theme::default();
        let s = render(&t);
        for k in ["font=", "size=12", "bg=", "surface=", "border=", "text=", "accent=", "warn=", "urgent="] {
            assert!(s.lines().any(|l| l.starts_with(k)), "{k} missing:\n{s}");
        }
        assert!(s.lines().filter(|l| !l.starts_with('#')).all(|l| !l.contains('#')), "colours are bare hex");
    }

    #[test]
    fn accessibility_scales_every_generated_ui_font_and_reduces_motion() {
        let mut t = Theme::default();
        t.accessibility.text_scale = 150;
        t.accessibility.reduce_motion = true;
        assert!(render(&t).contains("size=18\n"), "bar: 12 * 1.5");
        assert!(crate::gen::fuzzel::render(&t).contains(":size=16.5\n"), "menus: 11 * 1.5");
        assert!(crate::gen::lifenote::render(&t).contains("font-px=22.5\n"), "notifications: 15 * 1.5");
        let cmd = crate::cmd::lifewall_shell_cmd(&t);
        assert!(cmd.contains("--fps 2 ") && cmd.ends_with("--fps-battery 2"), "{cmd}");
        assert_eq!(crate::theme::Accessibility::default().scaled(11.0), 11.0);
    }
}
